insert into org.executor_tipo (codigo, nome, e_pessoa, e_maquina) select codigo, nome, e_pessoa, e_maquina from jsonb_to_recordset($j$[{"codigo": "P", "nome": "Pessoa do círculo", "e_pessoa": true, "e_maquina": false}, {"codigo": "A", "nome": "Agente", "e_pessoa": false, "e_maquina": true}, {"codigo": "R", "nome": "Automação", "e_pessoa": false, "e_maquina": true}, {"codigo": "H", "nome": "Pessoa de fora do círculo", "e_pessoa": true, "e_maquina": false}, {"codigo": "C", "nome": "Outro círculo", "e_pessoa": false, "e_maquina": false}, {"codigo": "X", "nome": "Assessoria", "e_pessoa": true, "e_maquina": false}]$j$::jsonb) as x(codigo org.executor, nome text, e_pessoa boolean, e_maquina boolean);
